def evaluate_all_at(X, y, psi, seeds=SEEDS, t=T_ESTIMATORS):
    """Evaluate all three ISER scores at one psi from a SINGLE fit per repeat.

    ISER-A/ISER-S/ISER-IF all read the same fitted Phi (R5-R7, R11), so one fit per
    repeat is enough; this keeps the default (no-search) run cheap on big datasets.
    Returns {method: (mean_auc, [per-seed auc])}.
    """
    per_seed = {m: [] for m in METHODS}
    for seed in seeds:
        model = build_isr(X, psi, seed, t=t)
        sc = scores_from_model(model, X)
        for m in METHODS:
            per_seed[m].append(auc(y, sc[m]))
    return {m: (float(np.mean(v)), [float(x) for x in v]) for m, v in per_seed.items()}

